connectedCallback() {
  if (this.delayConnectedCallback() || this.hasChildNodes()) {
    return;
  }
  MozXULElement.insertFTLIfNeeded("calendar/calendar.ftl");

  this.appendChild(this.constructor.fragment.cloneNode(true));

  this.classList.add("calendar-color-box", "calendar-item-container");
  this.style.pointerEvents = "auto";
  this.setAttribute("tooltip", "itemTooltip");
  this.setAttribute("tabindex", "-1");
  this.initializeItemAccessibility();
  this.addEventNameTextboxListener();
  this.initializeAttributeInheritance();
}

set parentBox(val) {
  this.mParentBox = val;
}

get parentBox() {
  return this.mParentBox;
}

set selected(val) {
  if (val && !this.mSelected) {
    this.mSelected = true;
    this.toggleAttribute("selected", true);
    this.setAttribute("aria-selected", "true");
    this.focus();
  } else if (!val && this.mSelected) {
    this.mSelected = false;
    this.removeAttribute("selected");
    this.setAttribute("aria-selected", "false");
    this.blur();
